SELECT COUNT(1)
FROM zo_his.adm_organization
WHERE parent_id = #{parentId}
  AND is_deleted = 0


        AND tenant_id = #{tenantId}


        AND tenant_id IS NULL

SELECT CASE WHEN
    EXISTS (
        SELECT 1 FROM zo_his.adm_encounter
        WHERE organization_id = #{departmentId} AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
    OR EXISTS (
        SELECT 1 FROM zo_his.adm_episode_of_care
        WHERE organization_id = #{departmentId} AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
    OR EXISTS (
        SELECT 1 FROM zo_his.cus_encounter_history
        WHERE (original_organization_id = #{departmentId}
            OR target_organization_id = #{departmentId})
          AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
    OR EXISTS (
        SELECT 1 FROM zo_his.adm_location
        WHERE organization_id = #{departmentId} AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
    OR EXISTS (
        SELECT 1 FROM zo_his.wkf_appointment_queue
        WHERE organization_id = #{departmentId} AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
    OR EXISTS (
        SELECT 1 FROM zo_his.wkf_schedule
        WHERE organization_id = #{departmentId} AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
    OR EXISTS (
        SELECT 1 FROM zo_his.wkf_slot
        WHERE organization_id = #{departmentId} AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
    OR EXISTS (
        SELECT 1 FROM zo_his.adm_healthcare_service
        WHERE offered_org_id = #{departmentId} AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
    OR EXISTS (
        SELECT 1 FROM zo_his.adm_practitioner
        WHERE org_id = #{departmentId} AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
    OR EXISTS (
        SELECT 1 FROM zo_his.adm_pr_assign
        WHERE org_id = #{departmentId} AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
    OR EXISTS (
        SELECT 1 FROM zo_his.bkg_schedule_template
        WHERE organization_id = #{departmentId} AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
    OR EXISTS (
        SELECT 1 FROM zo_his.bkg_slot_provision_template
        WHERE organization_id = #{departmentId} AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
    OR EXISTS (
        SELECT 1 FROM zo_his.bkg_week_schedule_template
        WHERE organization_id = #{departmentId} AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
    OR EXISTS (
        SELECT 1 FROM zo_his.bkg_calendar_exception
        WHERE organization_id = #{departmentId} AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
    OR EXISTS (
        SELECT 1 FROM zo_his.bkg_stop_clinic_slot_freeze
        WHERE organization_id = #{departmentId} AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
    OR EXISTS (
        SELECT 1 FROM zo_his.bkg_waitlist_entry
        WHERE organization_id = #{departmentId} AND is_deleted = 0

            AND tenant_id = #{tenantId}
            AND tenant_id IS NULL

    )
THEN 1 ELSE 0 END

