UPDATE zo_his.adm_organization SET is_deleted = 1, deleted_at = #{deletedAt}, deleted_by = #{deletedBy}, updated_at = #{deletedAt}, updated_by = #{deletedBy}, version = version + 1 WHERE id = #{id} AND is_deleted = 0 AND version = #{version}
AND tenant_id = #{tenantId}
AND tenant_id IS NULL

UPDATE zo_his.whale_organization_units
SET is_deleted = 1,
    deleted_at = #{deletedAt},
    deleted_by = #{deletedBy},
    updated_at = #{deletedAt},
    updated_by = #{deletedBy}
WHERE code = #{code}
  AND is_deleted = 0


        AND tenant_id = #{tenantId}


        AND tenant_id IS NULL

UPDATE zo_his.whale_sequence
SET current_value = #{value}
WHERE seq_key = #{seqKey}
  AND current_value < #{value}
